class MinStack:
    def __init__(self):
        self.values = []
        self.mins = []
    def push(self, value):
        self.values.append(value)
        self.mins.append(value if not self.mins else min(value, self.mins[-1]))
    def pop(self):
        self.mins.pop()
        return self.values.pop()
    def get_min(self):
        return self.mins[-1]

