class MinStackEncoded:
    def __init__(self):
        self.stack = []
        self.min_value = 0
    def push(self, value):
        if not self.stack:
            self.stack.append(0)
            self.min_value = value
        else:
            delta = value - self.min_value
            self.stack.append(delta)
            if delta < 0:
                self.min_value = value
    def pop(self):
        delta = self.stack.pop()
        value = self.min_value if delta < 0 else self.min_value + delta
        if delta < 0:
            self.min_value -= delta
        return value
    def get_min(self):
        return self.min_value

