export class MinStackEncoded {
  private stack: number[] = [];
  private minValue = 0;
  push(value: number): void {
    if (!this.stack.length) { this.stack.push(0); this.minValue = value; return; }
    const delta = value - this.minValue;
    this.stack.push(delta);
    if (delta < 0) this.minValue = value;
  }
  pop(): number {
    const delta = this.stack.pop()!;
    const value = delta < 0 ? this.minValue : this.minValue + delta;
    if (delta < 0) this.minValue -= delta;
    return value;
  }
  getMin(): number { return this.minValue; }
}

