from collections import deque

def serialize_level(root):
    out = []
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if not node:
            out.append('#')
            continue
        out.append(str(node.val))
        queue.append(node.left)
        queue.append(node.right)
    return ','.join(out)

