export function longestValidParentheses(s: string): number {
  const stack = [-1];
  let best = 0;
  for (let i = 0; i < s.length; i += 1) {
    if (s[i] === '(') stack.push(i);
    else {
      stack.pop();
      if (!stack.length) stack.push(i);
      else best = Math.max(best, i - stack[stack.length - 1]);
    }
  }
  return best;
}

