export function longestValidDp(s: string): number {
  const dp = Array(s.length).fill(0);
  let best = 0;
  for (let i = 0; i < s.length; i += 1) {
    if (s[i] !== ')') continue;
    const match = i - dp[i - 1] - 1;
    if (match >= 0 && s[match] === '(') {
      dp[i] = dp[i - 1] + 2 + (match > 0 ? dp[match - 1] : 0);
      best = Math.max(best, dp[i]);
    }
  }
  return best;
}

